import{_ as r}from"./chunks/ccd66e1d7657b907adf2.CM1BqmeM.js";import{_ as t,a as l}from"./chunks/f4c11b39801542b50b32.CEu4KDrg.js";import{_ as i,C as o,o as n,c as s,j as e,a as h,E as m,a5 as c}from"./chunks/framework.DNkHA0lr.js";const P=JSON.parse('{"title":"反细分领域（为什么没有细分领域会让你不可替代）","description":"","frontmatter":{"title":"反细分领域（为什么没有细分领域会让你不可替代）","originalTitle":"The Anti-Niche (Why Being Nicheless Makes You Irreplaceable)","date":"2023-12-02","originalUrl":"https://thedankoe.com/letters/the-anti-niche-why-being-nicheless-makes-you-irreplaceable/","minutes":18,"sourceHash":"4a67922184fde671bd13d16a085951e88faa66648a2c79170acabe0018dcdbbe","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/the-anti-niche-why-being-nicheless-makes-you-irreplaceable/"}]]},"headers":[],"relativePath":"letters/the-anti-niche-why-being-nicheless-makes-you-irreplaceable.md","filePath":"letters/the-anti-niche-why-being-nicheless-makes-you-irreplaceable.md"}'),g={name:"letters/the-anti-niche-why-being-nicheless-makes-you-irreplaceable.md"};function d(u,p,b,f,_,k){const a=o("ArticleMeta");return n(),s("div",null,[p[0]||(p[0]=e("h1",{id:"反细分领域-为什么没有细分领域会让你不可替代",tabindex:"-1"},[h("反细分领域（为什么没有细分领域会让你不可替代） "),e("a",{class:"header-anchor",href:"#反细分领域-为什么没有细分领域会让你不可替代","aria-label":'Permalink to "反细分领域（为什么没有细分领域会让你不可替代）"'},"​")],-1)),m(a),p[1]||(p[1]=c('<p><a href="https://www.youtube.com/embed/-9iGM346vRM?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p><img src="'+r+'" alt=""></p><p>在经历了多年的痛苦之后，我才意识到这一点。</p><p>当你初次踏上成为自由个体的旅程时，你听到的第一条建议所带来的那种难以忍受的痛苦：</p><p>“深耕细分领域。”</p><p>就像社会矩阵（social matrix）一样，也有一个商业矩阵。</p><p>社会矩阵是一个毫无根据的思想网络，它让社会能够凝聚运作。</p><p>政府和文化影响学校系统。学校系统为学生创造学习资源。学生不会质疑他们所学的东西。学生接着成为父母。父母把他们知道的教给孩子，并把他们送到学校。孩子们交朋友，为了融入社会而进一步顺从。孩子们长大，找工作，成为老师，成为父母，成为政治家，并创造影响文化的线上线下知识和资源。父母、学生和孩子去投票。这个循环继续着，创造了我们生活的社会。</p><p>商业矩阵也是同样的一个思想网络，它让企业按照“理应”的方式运作。</p><p>你是个人类。你通过接触初级知识，然后是中级和高级知识来学习。</p><p>问题是，谁从一开始就质疑过这些初级知识？</p><p>我们完全确信这是做事的最佳方式吗？</p><p>它是最有利于产生结果的吗？还是说它制造了更多的困惑，让人们过早地放弃了？</p><p>那些挣脱矩阵的人可以为所欲为。</p><p>但你无法在瞬间挣脱。</p><p>你必须了解游戏规则，并积累足够的经验，然后才能开始玩你自己的游戏。</p><h3 id="它从未说得通。它从未起效。直到" tabindex="-1">它从未说得通。它从未起效。直到…… <a class="header-anchor" href="#它从未说得通。它从未起效。直到" aria-label="Permalink to &quot;它从未说得通。它从未起效。直到……&quot;">​</a></h3><p>当我开始我的商业之旅时，我是从自由职业起步的。</p><p>我以为这是最“对新手友好”的选择，因为我所要做的只是“学习一项技能，出售一项技能”。</p><p>所以，我决定尝试用你能想到的几乎所有技能来做自由职业。</p><p>视频剪辑、平面设计、SEO、内容营销、Facebook广告，还有网页设计。</p><p>当时我称自己为一个“代运营公司（agency）”，因为听起来比自由职业者更酷。但其实只有我一个人。所以我不是什么代运营公司，我就是一个自由职业者。如果你没有员工，你也是。</p><p>（顺便说一下，人们并不在乎你是公司还是自由职业者）。</p><p>我的痛点总是挑选一个细分领域。</p><p>我会下载免费指南，在谷歌上无休止地搜索“最值得瞄准的100个细分领域”。</p><p>我瞄准过牙医、健身房、建筑公司等等。</p><p>这种做法有什么问题？</p><ul><li><strong>我根本不在乎这些人。</strong> 我会（而且确实）很讨厌和他们合作。对于你毕生事业这样重要的事情来说，这不是一个可持续的方法。你创业是有原因的，而不仅仅是为了找个新老板。</li><li><strong>我对他们的业务毫无经验。</strong> <em>大多数企业失败，是因为他们试图解决一个自己从未经历过的问题。</em> 记住这一点。当你无视这一点并最终失败时，随时欢迎回来找我。</li><li><strong>它把重心放在了<em>寻找</em>上，而不是吸引或成为。</strong> 你为了别人学习一项技能。你无休止地寻找客户去联系，结果花在开发线索上的时间，比建立杠杆（leverage）的时间还要多。</li></ul><p>难怪人们无法坚持建立一家企业。</p><p>在这个圈子里流传的商业意识形态已经统治太久了。</p><p>它们很肤浅，且缺乏对人性、心理学和成就感的尊重。</p><p>我将为你提供一个更好的方法，来打造属于你自己的独特细分领域。一种直观、有利可图且可持续的方法。</p><p><strong>能让你免受诸多痛苦的几个教训：</strong></p><ol><li><p>想要找到最佳细分领域的强烈愿望，是一个再明显不过的信号，说明你没有从大局上理解商业。原则对比战术，而“寻找最佳细分领域”只是一种战术。</p></li><li><p>打造一个<strong>你自己</strong>真正会购买、使用并从中受益的产品或服务。商业中没有多少捷径，但这就是其中之一。</p></li></ol><p>这两个教训改变了关于我的一切。</p><h2 id="最赚钱的细分领域就是你自己-将你的思想产品化" tabindex="-1">最赚钱的细分领域就是你自己（将你的思想产品化） <a class="header-anchor" href="#最赚钱的细分领域就是你自己-将你的思想产品化" aria-label="Permalink to &quot;最赚钱的细分领域就是你自己（将你的思想产品化）&quot;">​</a></h2><p><img src="'+t+'" alt=""></p><p>大多数人没有意识到他们属于一个非常特定的细分领域。</p><p>你关注了大量有着各种各样兴趣的人，正是这些塑造了你是谁。</p><p>这是打造细分领域时的第一个错误：</p><p>如果你的工作是锁定一个特定的人，而你自己就是一个特定的人，那你为什么非要把范围缩小到一个特定的兴趣，并围绕它来销售产品或服务呢？</p><p>不，这不会让你显得更权威。</p><p>不，人们也不会更信任你。</p><p>往好了说，你看起来就像一个披着“实操建议”外衣的高级搜索引擎。</p><p>往坏了说，你限制了受众的增长，且无法利用更广泛网络带来的杠杆。</p><p>如果一个人只谈论他选择的细分领域，比如面向企业家和高管的培训项目，他只会吸引那些人。</p><p>这并没有什么不好，但样本量太小了，而且这不是付费广告，你可以精准投放广告展示在这些人面前。</p><p>当他们只对那个细分领域喊话时：</p><ul><li>他们在起步阶段会更困难。</li><li>很少有人会分享他们的内容（他们无法出现在合适的人面前）</li><li>他们一年内可能涨粉到5,000人，而一个将自己各项兴趣融合起来的人一年内能涨粉到20,000人。</li></ul><p>3年后，由于复利效应，前者达到30,000粉，而后者达到300,000粉。</p><p>“但是Dan，那30万粉丝根本不在乎我的产品或服务。他们不是热门潜在客户。他们不会马上从我这里购买。他们毫无用处。”</p><p>这里有很多槽点需要拆解。</p><p>首先，如果这30万粉丝每人认识3-5个可以推荐给你的人，得益于网络效应，那就是90万到150万的受众。而与此同时，那个拥有3万粉丝、过度深耕细分领域的人，还在为了摆脱手动客户服务而苦苦挣扎，试图获得足够的杠杆。</p><p>其次，他们本来就不该马上找你购买。这正是一个教育品牌的全部意义。你<em>帮助</em>他们随着时间的推移，从初学者（通过内容）进阶到高级（通过产品）。</p><p>第三，没有哪个粉丝是毫无用处的，只是你太狭隘了，被过时的商业教条洗脑了，以至于你不明白人们可以学习新东西来改善自己的生活。</p><p>顺便说一句，我在<a href="https://digitaleconomics.school/" target="_blank" rel="noreferrer">数字经济学（Digital Economics）</a>中教授了所有这些内容。</p><h3 id="细分领域-就是一种世界观或视角" tabindex="-1">“细分领域”就是一种世界观或视角 <a class="header-anchor" href="#细分领域-就是一种世界观或视角" aria-label="Permalink to &quot;“细分领域”就是一种世界观或视角&quot;">​</a></h3><p><img src="'+l+'" alt=""></p><p>让我们来拆解一下细分领域到底是什么。</p><p>当你就是这个细分领域，而你又在不断变化时，你就是无细分领域的。</p><p>你不会把自己禁锢在那些你迟早会超越的技能或兴趣中，因为你是个人类。</p><p>为什么一开始大家都叫你要深耕细分领域？</p><p>这样你才能了解你的读者和客户的想法。</p><p>别人告诉你去创建一个客户画像，找出他们面临的紧迫问题，并向他们提供一个解决方案。（这个解决方案通常和其他产品一样，只做了一点小改动。关键在于，通过了解特定的人，让它<em>被感知</em>为对他们有价值。<strong>小技巧</strong>：重新创造已经存在的东西，但做得更好，不要把它搞得太复杂）。</p><p>那么，为什么我们不跳过所有这些流程，把我们自己当成客户画像，解决我们真正经历过的问题，并构建一个真正造福我们生活的解决方案呢？</p><p>这消除了赚钱过程中99%的猜测。</p><p>而且，你也不会落得跟不喜欢的人共事的下场。</p><p>本质上，客户画像就是你为其创作或向其营销的人的思想、世界观或视角。</p><p>从结构的角度来看，世界观或视角是由以下几部分组成的：</p><p><strong>1) 目标</strong></p><p>影响你每一个行动的有意识或无意识的目标，比如向前迈出一步或是去健身房。</p><p>自我生成的目标让你掌控自己的生活。</p><p>目标塑造了你解读情境的方式。一个被社会分配了60岁退休目标的人，比起一个自我设定了25岁财务自由目标的人，会把更少的商业机会看作是真正的机会。</p><p>目标同样也塑造了你（或者你的读者）解读书籍和内容的方式。拥有不同目标的两个人，在书籍和内容中画出的重点将截然不同。他们会注意到那些有助于实现他们目标的事物——不管他们是否意识到了这一点。</p><p><strong>2) 问题</strong></p><p>阻碍你实现目标或理想生活方式的有意识或无意识的问题。</p><p>营销的基础是随着时间的推移，提高读者对他们问题的认知水平。</p><p>如果你已经解决了自己的问题，并且正在帮助你的受众做同样的事，那么你就处于一个非常有利的地位。</p><p>认知的5个层级是：</p><ol><li><strong>无认知（Unaware）</strong> —— 没意识到他们的问题，以及它正在如何损害他们的生活质量。</li><li><strong>问题认知（Problem aware）</strong> —— 意识到了他们的问题，但不知道如何解决。</li><li><strong>方案认知（Solution aware）</strong> —— 意识到了他们的问题，并且知道有某种解决方案、教育或知识能够解决它。</li><li><strong>产品认知（Product aware）</strong> —— 意识到了他们的问题，并且知道有一条流线型的路径或系统能够解决它。</li><li><strong>深度认知（Most aware）</strong> —— 他们已经准备好改变，他们只需要一个正确的“为什么”，能够瞬间改变他们的行为。就像当你在书里读到一个观点，它改变了你整个人生观一样。</li></ol><p>当你的世界观就是你的细分领域时，你的工作就是以一种创造性的方式写作，提高人们对自己问题的认知。那样，他们就会为了实现目标而采取行动去寻找解决方案。</p><p><strong>3) 潜在路径</strong></p><p>世界观拼图的最后一块是清晰度。</p><p>当人们对下一步该怎么走不清晰时，他们会感到焦虑、不知所措或无聊。</p><p>这就是导致人际关系中争吵、商业中不和、以及政党间斗争的原因。</p><p>没有共同世界观的人，缺失了对方路径、叙事或系统中那些能让他们理解当前局面的拼图。</p><p><em>所以，当你就是那个细分领域时，你的工作就是创造一条整体的、循序渐进的路径，你可以与拥有相同世界观的读者分享这条路径，通常以你可以从中获得报酬的产品或服务的形式。</em></p><p>这样一来，他们就更有可能获得结果并理解你。</p><p>我的哲学思辨能把大量新人带入商业领域，这是有原因的。因为比起你随处可见的那些肤浅的商业大师，我让商业变得更说得通了。</p><p>除了目标、问题和潜在路径之外，人类心理的多个方面也会影响人们如何看待和应对目标与问题：</p><ul><li>过往经历</li><li>坚定与松散的信念</li><li>生活各个领域的技能水平</li></ul><p>以上所有这些，都可以是有意识的、无意识的、已知的或未知的。</p><p>作为一个教育品牌，你的全部工作就是提升受众的意识觉知。</p><p>让他们意识到自己的目标和问题。</p><p>让他们接触到生活中未知的潜能，并教育他们，直到这成为他们的已知。</p><p>你的细分领域是构成你世界观的宏大目标和迫切问题所在的<em>框架</em>。</p><p>你的工作是对受众的大脑进行编程，让他们接受这个框架（或世界观），追求那些目标，并解决那些问题。</p><p>为了过上有目标感的生活，这是一项艰巨但令人满足的事业。</p><p>它要求你终生发展自我，并随着引导麾下社区的责任而不断进化。</p><p>细分领域理应是具体的，还有什么比这更具体呢？</p><p>一个能改变你（以及你的读者）生活的理想目标。</p><p>一个能减轻你（以及你的读者）痛苦的迫切问题。</p><p>一条能为你（以及你的读者）带来清晰度的明确路径、系统或解决方案。</p><p>这些目标和问题几乎总是与他人的相似。</p><p>在永恒的市场中，每个人都有着相同的目标和问题：健康、财富、人际关系和幸福。</p><p>但这条路径……</p><p>这条路径对你来说是独一无二的。</p><p>每个人都渴望财务自由，但两个人<em>必须</em>走不同的路径。</p><p>你可能会走社交媒体和在线业务的路线，从事电子商务，并具备与之相关的独特技能、心态和经验。</p><p>另一个人可能会走投资和房地产的路线，具备另一种独特的技能与兴趣组合。</p><p>记住，你学到的<em>其他每一个兴趣</em>也会影响你对情况的认知。</p><p>如果写日记、散步或玩电子游戏包含在这条路径中，无论它们对实现目标的作用有多直接，都依然在你实现目标的过程中发挥了作用。</p><p>正是这条路径塑造了现在的你。</p><p>你在实现目标的过程中处理的所有信念、技能和数十亿比特的信息，构成了世界上最独特的细分领域。</p><p>如果你能在数百篇帖子、时事通讯、产品和互动中阐明你的路径——那就是你创造“一人细分领域”（niche of one）的方式。</p><p>你的工作就是在互联网上记录你的生活，让真实带来的回报发挥它们的魔力。</p><p>你的工作是吸引一个特定的群体。你通过以自己能理解的方式写下想法来实现这一点。从你的世界观出发。从你的视角出发。这个特定的群体就是那些与你性格相同的人。这就是你如何为自己打造一款无需市场调研就能畅销的产品。</p><h3 id="你的人生之书——如何创造你的一人细分领域" tabindex="-1">你的人生之书——如何创造你的一人细分领域 <a class="header-anchor" href="#你的人生之书——如何创造你的一人细分领域" aria-label="Permalink to &quot;你的人生之书——如何创造你的一人细分领域&quot;">​</a></h3><p>当你在互联网上记录生活时，你就在创造你的一人细分领域。</p><p>你过去、现在和未来自我的心态与技能，应该以一种有说服力的方式呈现出来，去吸引那些性格相似、但比你落后几步的人，这样你才能真正帮助到他们。</p><p>你要为你将要写的一本关于你人生的书列出大纲结构。</p><p>这将用于模式识别和内容创作。</p><p>在消费信息时，使用这个大纲来捕捉灵感。</p><p>同时，把它作为一个内容计划，在6到12个月的时间里撰写时事通讯、长推文/轮播图和短文（这正是让你的受众真正熟悉你所需的时间）。</p><p>带着这个想法，填写下面的书籍结构，就好像你在写给那些落后你1到3步的人一样。</p><p>你可以将这份书籍大纲与我的<a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">两小时写手（2 Hour Writer）</a>课程结合使用，写出真正能带来读者增长的内容。</p><p><strong>书籍引言：你的故事</strong></p><p>你的故事就是你的品牌。理清你的故事非常重要，这样你才能用它从独特的角度来构建内容的框架。</p><p>你几乎可以用个人经历来作为任何写作的开篇。单凭这一点，就能让它与众不同，而不像其他那些肤浅的文章。</p><ul><li>你是从哪里开始的？</li><li>你经历过哪些挣扎？</li><li>你这段旅程的高潮是什么？</li><li>你取得了哪些令人向往的成就？</li><li>哪些主题、兴趣或技能帮助你到达了那里？</li></ul><p><strong>第一部分：哲学</strong></p><p>你需要让人们与你达成共识。</p><p>你的哲学就是你对“一个人如何过上好日子？”这个问题的答案。</p><p>你必须不断地以一种导向你理想未来（或避开你品牌“敌人”）的方式，阐明你的信念和行动的重要性。</p><ul><li>详细描述你的理想未来和生活方式。你要带领追随者实现什么目标？</li><li>描述那个敌人。你想避之不及的未来和生活方式是怎样的？</li><li>你有哪些别人会认为极端或冒犯的信念？</li><li>为了帮助你迈向理想的生活方式，你所学的每个主题、兴趣或技能分别有什么重要性？</li></ul><p>花点时间做这件事。这个大纲会相当庞大。</p><p>这些问题的答案将构成你大部分的内容灵感，为你带来大量的增长。</p><p><strong>第二部分：教育</strong></p><p>这是你建立权威的方式。</p><p>你的工作是就这些技能或兴趣教育他人</p><p>不折不扣地<em>教授</em>他们这项技能或兴趣，以及你是如何学会它的。关于这一点只能说这么多。你并没有在创造任何新东西。你只是在<em>你的</em>品牌下创建了一个信息库——这样人们就可以向你学习。</p><p>不要掉进这样的陷阱：“他们可以在网上其他地方学到这些信息。”</p><p>假设他们没有动力去别处学习，而<em>你</em>必须把信息提供给他们。</p><p>正如我们将在下一节讨论的那样，<em>人们会记住第一个教给他们有用知识的人</em>。去成为更多人的那个人吧。</p><p><strong>第三部分：实践</strong></p><p>创建渐进式的系统和实践，让你的读者可以用来在你的技能和兴趣上变得更强。</p><p>作为彩蛋，把你的名字冠在这些方法上。</p><p>如果你想为了生产力重新创造一个类似“艾森豪威尔矩阵”的东西，那就去做。</p><p>不要干巴巴地教授那个概念或模型，拿来它，并以一种可能获得更好结果的方式创造属于你自己的版本。</p><p>行为改变是权威和认可的驱动力。</p><p>当你在社交媒体上花时间写书时，你建立的品牌就能将99%的人甩在身后。</p><h2 id="兴趣心理学——如何谈论任何你想谈论的话题并依然能赚钱" tabindex="-1">兴趣心理学——如何谈论任何你想谈论的话题并依然能赚钱 <a class="header-anchor" href="#兴趣心理学——如何谈论任何你想谈论的话题并依然能赚钱" aria-label="Permalink to &quot;兴趣心理学——如何谈论任何你想谈论的话题并依然能赚钱&quot;">​</a></h2><p>自从我开始改变在线业务的格局以来，我几乎每天都会收到这个问题：</p><p><em>“我想谈论更多我的兴趣，但如果互动率很低，或者我的受众不喜欢怎么办？”</em></p><p>首先，你要理解内容和产品之间的分离。</p><p>人们认为内容全是关于促销的。他们觉得只应该写那些能带来销售和线索的内容。</p><p>他们认为应该把写的所有东西都垂直细分——而不是<em>为一个产品准备一个具体且引人注目的落地页，一次性建立起权威，<strong>这样你就不必在内容中一直谈论它了。</strong></em></p><p>在内容中东敲西打地测试推销产品的想法，然后利用这些想法来构建落地页，这个页面将作为永久存在的静态内容，供你添加链接。</p><p>我太常看到这种情况了：</p><p>人们发布的只是产品的图片或更新。</p><p>或者他们发了个帖子带着</p><p>他们从不展示自己作为人类的一面。</p><p>他们从不提供教育、娱乐或启发（你要知道，这些才是人们在社交媒体上真正关注和驻足的东西）。</p><p>他们只是在兜售。</p><p>没有人会关注公司账号。</p><p>人们关注的是教育者、娱乐者和启发者。</p><p>红牛（RedBull）拥有庞大的粉丝群，因为他们在Instagram上没有一张产品图片。全是关于人们因为红牛而过上的那种生活方式的启发性内容。</p><p>如果你所做的只是谈论你的产品，那么恭喜你，这绝对是让你的品牌永远无法成长、无法拥有高参与度读者，也永远看不到收入指数级增长的绝佳方法。</p><p>个人品牌是你的业务、产品或服务最强大的流量来源。</p><p>所以，让我们先把它颠倒过来思考。</p><p>如果你只谈论能让你赚钱的技能，会发生什么？</p><ul><li><strong>你的互动率很低。</strong>如果你的内容没有被分享，你该如何成长，以便拥有<em>更多</em>的人去推销？</li><li><strong>你无法建立信任或权威。</strong>不要再想着必须现在就变现，开始设想你将在12个月后变现（这样做反而会让你现在变现得更快）。</li><li><strong>人们不喜欢你。</strong>如果你有朝一日想转型卖别的东西，你将无能为力。你被困在了你一直推销的那个细分领域里。</li></ul><p>人们有多种兴趣。</p><p>人们可以培养新的兴趣。</p><p>你可以让自己的兴趣变得有趣，从而让人们对它们产生兴趣。</p><p>这就是把观众变成粉丝，再变成超级粉丝的秘诀。</p><p>有人可能会因为一个兴趣而关注你，就像你在看了一部由“巨石”道恩·强森主演的电影后会关注他一样。</p><p>现在他们是观众。</p><p>然后你分享了他们的另一个兴趣，或者向他们介绍了一些新东西，就像巨石强森发布关于健身和营养的内容一样。</p><p>现在他们成了粉丝。</p><p>接着他们发现了构成其心态的信念或价值观，就像巨石强森重视感恩和努力工作一样。</p><p>现在他们成了超级粉丝。</p><p>（顺便说一句，每个人都应该在内容中加入关于心态的探讨，这正是吸引广泛受众的原因，因为它适用于每个人）。</p><p>谈论不止一个兴趣，是你变得不可替代的方式。</p><p>最顶尖的个人品牌在无意中就做到了这一点。</p><p>他们只发布<em>他们</em>认为对自己重要的东西，并试图向你阐明这种重要性。</p><p>以下是你开始这样做的步骤：</p><p><strong>1) 专注于教育</strong></p><p>代入你过去自我的视角——一个绝对的新手。</p><p>他们该<em>如何</em>以更好的方式达到你现在的位置？</p><p><strong>2) 专注于理解</strong></p><p>拉开视角，找出你追随者知识中的空白。</p><p>他们需要知道<em>什么</em>才能与你达成共识？</p><p><strong>3) 专注于重要性</strong></p><p>分析你的生活，意识到你为什么做你正在做的事。</p><p><em>为什么</em>你只拥有这些特定的技能和信念，而不是其他成千上万你本可以拥有的东西？<em>为什么</em>你走上了现在这条路，而不是另一条？</p><h3 id="宽泛的品牌-具体的产品-如何真正落实细分领域" tabindex="-1">宽泛的品牌，具体的产品（如何真正落实细分领域） <a class="header-anchor" href="#宽泛的品牌-具体的产品-如何真正落实细分领域" aria-label="Permalink to &quot;宽泛的品牌，具体的产品（如何真正落实细分领域）&quot;">​</a></h3><p>你可能会问：“Dan，如果我不写任何与我销售的东西相关的内容，我怎么能卖出东西呢？”</p><p>首先，你还是会偶尔写到它，这样人们才会知道你是做什么的。</p><p>其次，你对什么是真正的营销并没有扎实的理解。</p><p>你几乎从来不需要直接谈论你兜售的技能。</p><p><em>你要谈论的是它将如何改变他们的生活。它将如何引发一场蜕变。它将如何填补他们当前现状与理想未来之间的鸿沟。</em></p><p>你在描绘他们渴望的生活，让他们意识到自己面临的问题，并把产品作为解决方案呈现给他们。</p><p>基于这一点，你可以这样看待垂直细分：</p><p>你的品牌是一个广泛吸引同类人的引力场。</p><p>你的内容是一种媒介，让人们意识到他们生活中的理想目标和迫切问题。</p><p>而你的第一个基础产品，就是连接两者的桥梁。</p><p>你不必持续写关于你产品的内容，因为你有一个叫做“落地页”的东西，它接过了你内容未尽的使命。落地页是静态的数字资产，不会像内容那样转瞬即逝。</p><p>所以，去当一会儿疯狂科学家吧。</p><p>规划出一份新闻通讯、一份免费指南、一款低客单价产品，以及一项高客单价服务（如果你正在建立一个庞大而非特定细分领域的受众群体，高客单价服务是可选的）。</p><p>你的新闻通讯应该全部托管在博客上，这样你就可以将最优秀的文章推荐给感兴趣的读者阅读。</p><p>你的免费指南着陆页及其内容旨在教育受众，引导他们成为你产品的客户。这是针对你受众中一个更具体的问题量身定制的。</p><p>你的产品着陆页会从你上次停下的地方继续，让人们意识到他们可以更快地解决自己的问题。</p><p>这就是你深耕细分领域的方式。</p><p>你部署数字地产，撰写基于世界观的内容，并每天持续引导人们依次访问你的新闻通讯、免费指南和产品。</p><h3 id="你的细分领域、品牌和产品的演化" tabindex="-1">你的细分领域、品牌和产品的演化 <a class="header-anchor" href="#你的细分领域、品牌和产品的演化" aria-label="Permalink to &quot;你的细分领域、品牌和产品的演化&quot;">​</a></h3><p>解决你自己的问题，并出售解决方案。</p><p>不是一次，而是永远。</p><p>随着你达到人生新高度，你的品牌、内容和产品也会随之演化。</p><p>当旧产品失去效力时，你将被迫创造新产品。这不是一件坏事，它实际上能让你维持并增加年收入。</p><p>自从 4 年前起步以来，我几乎每个季度都会推出新东西。</p><p>从网页设计和自由职业，到营销咨询，到实体生产力手帐，到社交媒体增长，到自我提升，到写作，到商业大师课，到短期训练营，到一本书，再到现在基于我创建的系统开发出一款软件（几乎没人能复制它，因为他们的路径与我不一样）。</p><p>你必须进行实验并不断迭代。</p><p>这是防止品牌熵增，且不会因为社交媒体的本质而慢慢消亡的唯一途径。你必须不断进化。</p><p>这封信就写到这里。</p><p>希望对你有所帮助。</p><p>Dan</p><hr><p><a href="/en/letters/the-anti-niche-why-being-nicheless-makes-you-irreplaceable">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',229))])}const x=i(g,[["render",d]]);export{P as __pageData,x as default};
